    WHEN 'Refining Charge Payble' THEN 'LIABILITY'
    WHEN 'Refining Charge Payble - Gold' THEN 'LIABILITY'
    WHEN 'Refining Charge Payble - Silver' THEN 'LIABILITY'
    WHEN 'Repair & Maintenance' THEN 'EXPENSE'
