    WHEN 'Shop Expensses' THEN 'EXPENSE'
    WHEN 'Shop Rent' THEN 'EXPENSE'
    WHEN 'Staff Bonus Expensses' THEN 'EXPENSE'
    WHEN 'Staff Incentive' THEN 'EXPENSE'
    WHEN 'Staff LIC' THEN 'EXPENSE'
    WHEN 'Staff Salary' THEN 'EXPENSE'
    WHEN 'Staff Uniform' THEN 'EXPENSE'
    WHEN 'Staff Welfare' THEN 'EXPENSE'
    WHEN 'Sundry Creditors' THEN 'LIABILITY'
    WHEN 'Sundry Creditors (other)' THEN 'LIABILITY'
    WHEN 'Sundry Debtors' THEN 'ASSET'
    WHEN 'TDS Payable F Yr 2016-17' THEN 'LIABILITY'
    WHEN 'Tax Invoice Party' THEN 'ASSET'
    WHEN 'Tax Invoice Sale' THEN 'INCOME'
    WHEN 'Telephone Charges' THEN 'EXPENSE'
    WHEN 'Traveling & Conveyance' THEN 'EXPENSE'
    WHEN 'VAT Payble' THEN 'LIABILITY'
    ELSE "accountType" END
WHERE "narration" = 'Migrated from legacy ledger';


-- ===== v3.1 migration (20261005100000_v31_item_barcodes) =====
-- v3.1: barcodes move from Product to Item (item code for MRP goods; every piece keeps its own
-- Inventory.barcodeNo), plus token versioning for immediate session revocation. Idempotent.

ALTER TABLE "Item" ADD COLUMN IF NOT EXISTS "barcode" TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS "Item_storeId_barcode_key" ON "Item"("storeId", "barcode");

-- Carry any product barcode over to the product's single item (only when unambiguous), then drop it.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'Product' AND column_name = 'barcode') THEN
    UPDATE "Item" i SET "barcode" = p."barcode"
    FROM "Product" p
    WHERE p."barcode" IS NOT NULL AND i."productId" = p.id AND i."barcode" IS NULL
      AND (SELECT count(*) FROM "Item" x WHERE x."productId" = p.id) = 1;
  END IF;
END $$;
DROP INDEX IF EXISTS "Product_storeId_barcode_key";
ALTER TABLE "Product" DROP COLUMN IF EXISTS "barcode";

ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "tokenVersion" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Store" ADD COLUMN IF NOT EXISTS "tokenVersion" INTEGER NOT NULL DEFAULT 0;

-- ---------------------------------------------------------------------------
-- Prisma migration history (so `npx prisma migrate deploy` works from here on)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
  "id" VARCHAR(36) PRIMARY KEY NOT NULL,
  "checksum" VARCHAR(64) NOT NULL,
  "finished_at" TIMESTAMPTZ,
  "migration_name" VARCHAR(255) NOT NULL,
  "logs" TEXT,
  "rolled_back_at" TIMESTAMPTZ,
  "started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "applied_steps_count" INTEGER NOT NULL DEFAULT 0
);
INSERT INTO "_prisma_migrations" (id, checksum, finished_at, migration_name, applied_steps_count)
SELECT gen_random_uuid()::text, '5f48a4e3daf9295bcc0cca664cc2be6fcb4b49d953e796266922897e96002579', now(), '20260929070033_init', 1
WHERE NOT EXISTS (SELECT 1 FROM "_prisma_migrations" WHERE migration_name = '20260929070033_init');
