SELECT gen_random_uuid()::text, '29338146f3fe34c2f7093633898718d7e74d5b351045bfc3b05d36e5df898c58', now(), '20261003100000_v3_hardening', 1
WHERE NOT EXISTS (SELECT 1 FROM "_prisma_migrations" WHERE migration_name = '20261003100000_v3_hardening');
