-- ---------------------------------------------------------------------------
-- Customer master backfill from migrated sales (store 1): one customer per valid
-- 10-digit phone, latest name/address on record. Historical sales are linked to it.
-- ---------------------------------------------------------------------------
WITH src AS (
  SELECT DISTINCT ON (p) p, s."customerName", s."customerAddress", s."customerCity", s."customerState", s."customerPan", s."customerGst", s."storeId"
  FROM (SELECT right(regexp_replace(COALESCE("customerPhone", ''), '\D', '', 'g'), 10) AS p, * FROM "Sale") s
  WHERE s."storeId" = 1 AND length(s.p) = 10 AND s.p ~ '^[6-9]'
    AND NOT EXISTS (SELECT 1 FROM "Customer" c WHERE c."storeId" = s."storeId" AND c.phone = s.p)
  ORDER BY p, s."saleDate" DESC, s.id DESC
), numbered AS (
  SELECT src.*, (SELECT COALESCE(MAX("lastCustomerNumber"), 0) FROM "StoreCounter" WHERE "storeId" = 1)
                + row_number() OVER (ORDER BY p) AS seq
  FROM src
)
INSERT INTO "Customer" ("customerCode", name, phone, address, city, state, pan, gst, "storeId", "updatedAt")
SELECT 'C1-' || lpad(seq::text, 6, '0'), COALESCE(NULLIF(trim("customerName"), ''), 'Customer'), p,
       NULLIF(trim("customerAddress"), ''), NULLIF(trim("customerCity"), ''), COALESCE(NULLIF(trim("customerState"), ''), 'ODISHA'),
       NULLIF(trim("customerPan"), ''), NULLIF(trim("customerGst"), ''), 1, now()
FROM numbered;

UPDATE "StoreCounter" SET "lastCustomerNumber" = GREATEST("lastCustomerNumber",
  COALESCE((SELECT MAX(substring("customerCode" from 4)::int) FROM "Customer" WHERE "storeId" = 1 AND "customerCode" ~ '^C1-[0-9]{6}$'), 0))
WHERE "storeId" = 1;

UPDATE "Sale" s SET "customerId" = c.id
FROM "Customer" c
WHERE s."storeId" = 1 AND s."customerId" IS NULL AND c."storeId" = 1
  AND c.phone = right(regexp_replace(COALESCE(s."customerPhone", ''), '\D', '', 'g'), 10);


