UPDATE "Voucher" v SET "saleId" = s.id, "referenceDocNo" = s."invoiceNo" FROM "Sale" s WHERE v."referenceType" = 'RetailInvoice' AND v."saleId" IS NULL AND s."storeId" = v."storeId" AND s."invoiceNo" = substring(v.narration from 'No\.\s*(\S+)\s*$');

