UPDATE "Purchase" p SET "customerPhone" = s."customerPhone", "customerId" = s."customerId" FROM "SaleOldGold" g JOIN "Sale" s ON s.id = g."saleId" WHERE g."purchaseId" = p.id AND p.id BETWEEN 800001 AND 899999 AND p."customerPhone" IS NULL AND s."customerPhone" ~ '^[6-9][0-9]{9}$';

UPDATE "Voucher" SET "advanceReceiveId" = a.id, "referenceDocNo" = 'APR/19-20/1' FROM "AdvanceReceive" a WHERE "Voucher".id = 74 AND a."storeId" = 1 AND a.specification LIKE '%APR/19-20/1%';
