WHERE a."storeId" = 1 AND (a.specification LIKE '%(voucher ' || v.vrno || ')%' OR a.specification LIKE 'Migrated advance ' || v.vrno || '%');
UPDATE "AdvanceReceive" a SET "customerId" = c.id FROM "Customer" c WHERE a."customerId" IS NULL AND c."storeId" = a."storeId" AND c.phone = right(regexp_replace(COALESCE(a."contactNumber", ''), '\D', '', 'g'), 10);
-- Advance adjustments on sales: 10
INSERT INTO "SaleAdvanceAdjustment" ("saleId", "advanceReceiveId", amount, "adjustedAmount", "previousBalance", "remainingBalance", "storeId", "createdAt")
SELECT v.sid, a.id, v.amt, v.amt, v.total, GREATEST(v.total - v.amt, 0), 1, s."saleDate"
FROM (VALUES
  (208, 'APR/19-20/1', 19000.0, 19000.0),
  (198, 'APR/19-20/2', 35000.0, 35000.0),
  (2229, 'APR/23-24/1', 4000.0, 4000.0),
  (2256, 'APR/23-24/2', 60000.0, 60000.0),
  (59958, 'APR/25-26/1', 20000.0, 20000.0),
  (102017, 'APR/25-26/4', 30000.0, 30000.0),
  (102025, 'APR/25-26/5', 30000.0, 30000.0),
  (102027, 'APR/25-26/6', 7500.0, 7500.0),
  (102034, 'APR/25-26/7', 2200.0, 2200.0),
  (103040, 'APR/25-26/8', 552000.0, 552000.0)
) AS v(sid, vrno, amt, total)
JOIN "Sale" s ON s.id = v.sid JOIN "AdvanceReceive" a ON a."storeId" = 1 AND a.specification LIKE 'Migrated advance ' || v.vrno || '%'
ON CONFLICT ("saleId", "advanceReceiveId") DO NOTHING;

