UPDATE "Purchase" p SET date = x.d, "createdAt" = x.d FROM (SELECT "purchaseId" pid, MIN("createdAt") d FROM "Inventory" WHERE "purchaseId" IN (900001, 900002) GROUP BY 1) x WHERE p.id = x.pid;

-- Item default purity = the purity most of its migrated pieces carry (legacy items had none).
UPDATE "Item" i SET "purityId" = x.pid FROM (
  SELECT DISTINCT ON ("itemId") "itemId" iid, "purityId" pid FROM "Inventory"
  WHERE "storeId" = 1 AND "itemId" IS NOT NULL AND "purityId" IS NOT NULL
  GROUP BY "itemId", "purityId" ORDER BY "itemId", count(*) DESC, "purityId"
) x WHERE i.id = x.iid AND i."purityId" IS NULL AND i."storeId" = 1;

-- Whitespace clean-up
UPDATE "Customer" SET address = NULLIF(btrim(regexp_replace(address, '[\r\n]+', ' ', 'g')), '') WHERE address ~ '[\r\n]';
UPDATE "Sale" SET "customerAddress" = NULLIF(btrim(regexp_replace("customerAddress", '[\r\n]+', ' ', 'g')), '') WHERE "customerAddress" ~ '[\r\n]';
UPDATE "Purchase" SET address = NULLIF(btrim(regexp_replace(address, '[\r\n]+', ' ', 'g')), '') WHERE address ~ '[\r\n]';

SELECT setval(pg_get_serial_sequence('"SaleOldGold"','id'), GREATEST((SELECT COALESCE(MAX(id),1) FROM "SaleOldGold"), 1));
SELECT setval(pg_get_serial_sequence('"SaleAdvanceAdjustment"','id'), GREATEST((SELECT COALESCE(MAX(id),1) FROM "SaleAdvanceAdjustment"), 1));
SELECT setval(pg_get_serial_sequence('"Inventory"','id'), GREATEST((SELECT COALESCE(MAX(id),1) FROM "Inventory"), 1));
SELECT setval(pg_get_serial_sequence('"PurchaseItem"','id'), GREATEST((SELECT COALESCE(MAX(id),1) FROM "PurchaseItem"), 1));

COMMIT;
